INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(121650, 'ruRU', '', '<Получить Мастерство лей-линий за 10 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t Древней маны.>', 24330),
(121687, 'ruRU', '', 'Среди нас скрываются предатели Великой Магистрикс, прямо у нас под носом. Мы найдём их и положим конец этому сопротивлению!', 24330),
(121688, 'ruRU', '', 'Если горожане не станут подчиняться, мы будем править силой и страхом. Сопротивление Великой Магистрикс близится к концу!', 24330),
(121693, 'ruRU', '', 'Будучи друидом-дикарём, твоё главное оружие — смена облика. В Облике кота твои когти и клыки раздирают противников, заставляя их кровоточить.', 24330),
(121724, 'ruRU', '', 'Узрите, враг среди нас!', 24330),
(121725, 'ruRU', '', 'Тебе не скрыть, кто ты есть на самом деле, демон!', 24330),
(121726, 'ruRU', '', 'Среди нас ещё больше таких!', 24330),
(121734, 'ruRU', '', 'Ты обнаружил нас слишком поздно, иллидари! КЛИНОК СКВЕРНЫ, В АТАКУ!', 24330),
(121740, 'ruRU', '', 'Нам нужно укрепить наши ряды. Найди иссохших и успокой их ярость. Я призову их в Шал''Аран.', 24330),
(121741, 'ruRU', '', 'Отличная работа. Я не сомневаюсь, что каждый из них будет рад помочь нашему делу.', 24330),
(121752, 'ruRU', '', 'Ещё раз спасибо за то, что спас мою шкуру от тех морских гигантов, $n.', 24330),
(121758, 'ruRU', '', 'Их ярость меркнет перед моей, Иллидан. У нас с тобой есть незакрытые дела.', 24330),
(121759, 'ruRU', '', 'Моя долгая охота наконец окончена. Сегодня правосудие восторжествует!', 24330),
(121760, 'ruRU', '', 'Всё кончено. Ты побеждён.', 24330),
(121761, 'ruRU', '', 'Он прав. Я ничего не чувствую... Я... ничто.', 24330),
(121762, 'ruRU', '', 'Прощайте, защитники.', 24330),
(121765, 'ruRU', '', 'Привет, $c. Полагаю, ты здесь, чтобы помочь иллидари уничтожить Пылающий Легион?', 24330),
(121766, 'ruRU', '', 'Привет, $n. С тобой во главе Легион на Фаронааре падёт в скором времени.', 24330),
(121771, 'ruRU', '', 'Благодарю за твою помощь на Фаронааре, $n. Мне стыдно, что один из наших стал предателем и превратился в одного из Демоноослепленных для Пылающего Легиона.\n\nМы заставим их заплатить.', 24330),
(121773, 'ruRU', '', 'Благодарю за то, что спас нас на Фаронааре, $n.\n\nНе могу поверить, что Циана стала предательницей. Она предала нас всех. Есть и другие, что также стали Демоноослепленными. Мы выследим их и убьём вместе с их новыми хозяевами из Легиона.\n\nКлянусь в этом!', 24330),
(121775, 'ruRU', '', '$n, как проходит бой? Нужны припасы или что-то отремонтировать?', 24330),
(121776, 'ruRU', '', '$n, Пылающий Легион отправляет против нас самых могущественных демонов из своего арсенала. Они не намерены проиграть эту третью войну и не остановятся ни перед чем, чтобы стереть всех нас с лица Азерота.\n\nВместе мы отплатим им тем же.', 24330),
(121778, 'ruRU', '', 'Предложение: 1200x |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF Древняя мана|h|r', 24330),
(121786, 'ruRU', '', 'Ну, привет, мой дорогой. Надеюсь, ты не против. Альтруис попросил меня помочь перевезти сюда часть твоих сил.\n\nПохоже, Легион неплохо закрепился на том острове вон там. Он решил, что лучше не позволять им захватить всю Азсуну.\n\nНе волнуйся, я перевожу иллидари туда-сюда с Демонического Молота по мере необходимости. Твои силы готовы собраться и отправиться куда угодно по первому твоему слову.', 24330),
(121787, 'ruRU', '', 'Ну, привет, мой дорогой. Надеюсь, ты не против. Кейн попросил меня помочь перевезти сюда часть твоих сил.\n\nПохоже, Легион неплохо закрепился на том острове вон там. Он решил, что лучше не позволять им захватить всю Азсуну.\n\nНе волнуйся, я перевожу иллидари туда-сюда с Демонического Молота по мере необходимости. Твои силы готовы собраться и отправиться куда угодно по первому твоему слову.', 24330),
(121814, 'ruRU', '', '<Получить Оберег Первого Чародея за 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t Древней маны.>', 24330),
(121818, 'ruRU', '', 'Нам нужно удержать его любой ценой!', 24330),
(121819, 'ruRU', '', 'Удержите его!', 24330),
(121820, 'ruRU', '', 'Сосредоточьтесь! Нельзя дать ему вырваться!', 24330),
(121821, 'ruRU', '', 'Эта земля теперь наша!', 24330),
(121822, 'ruRU', '', 'Нет... этого не может быть!', 24330),
(121823, 'ruRU', '', 'Крррггхааавв!', 24330),
(121824, 'ruRU', '', 'Мать Колдовства повелевает этим!', 24330),
(121825, 'ruRU', '', 'Нас не остановить!', 24330),
(121826, 'ruRU', '', 'Плоть и кость — в землю и камень!', 24330),
(121827, 'ruRU', '', 'Сорвите плоть и разбросайте кости!', 24330),
(121828, 'ruRU', '', 'Тебе не... избежать... проклятия!', 24330),
(121830, 'ruRU', '', 'Глупец! Умри!', 24330),
(121831, 'ruRU', '', 'Аах... будь ты проклят!', 24330),
(121832, 'ruRU', '', 'Узри моё проклятие!', 24330);
